create table if not exists public.pompkin_payment_methods(id uuid primary key default gen_random_uuid(),name text not null unique,account_name text,account_number text,instructions text,active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.pompkin_payments(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.pompkin_orders(id) on delete cascade,user_id uuid not null references public.profiles(id),amount numeric(10,2) not null,method_id uuid references public.pompkin_payment_methods(id),reference text,status text not null default 'submitted',created_at timestamptz not null default now());
create table if not exists public.pompkin_payment_proofs(id uuid primary key default gen_random_uuid(),payment_id uuid not null references public.pompkin_payments(id) on delete cascade,user_id uuid not null references public.profiles(id),image_url text not null,created_at timestamptz not null default now());
alter table public.pompkin_payment_methods enable row level security; alter table public.pompkin_payments enable row level security; alter table public.pompkin_payment_proofs enable row level security;
create policy payment_methods_read on public.pompkin_payment_methods for select using(active or public.is_pompkin_admin()); create policy payments_customer on public.pompkin_payments for all using(user_id=auth.uid() or public.is_pompkin_admin()) with check(user_id=auth.uid() or public.is_pompkin_admin()); create policy proofs_customer on public.pompkin_payment_proofs for all using(user_id=auth.uid() or public.is_pompkin_admin()) with check(user_id=auth.uid() or public.is_pompkin_admin());
